		playerLines = "你对这样的景象作何感想？",
		dialogType = 2,
		Background_Position = "313.56=694.00",
		playerName = "接头人",
		background = "98lajichang",
		playerId = "4999",
		id = "2309200423",
		playerPosType = 0,
		isStay = 0
	},
	["2309200424"] = {
		classId = 23092004,
		index = 24,
		playerLines = "普通人面对资本的浪潮根本无力反抗，毕竟自己的身家性命都攥在别人手里。",
		Background_Scale = "1.90",
		dialogType = 2,
		Background_Position = "313.56=694.00",
		playerName = "班长",
		background = "98lajichang",
		playerId = "4999",
		id = "2309200424",
		playerPosType = 0,
		isStay = 0
	},
	["2309200425"] = {
		classId = 23092004,
		index = 25,
		Background_Scale = "1.90",
		playerLines = "而资本又会屈从于更大的资本，类似大鱼吃小鱼，小鱼吃虾米一样的生态链吧。",
		dialogType = 2,
		Background_Position = "313.56=694.00",
		playerName = "班长",
		background = "98lajichang",
		playerId = "4999",
		id = "2309200425",
		playerPosType = 0,
		isStay = 0
	},
	["2309200426"] = {
		classId = 23092004,
		index = 26,
		playerLines = "说得好，现在你明白我们为什么想要推翻VLife的独裁了吧？",
		Background_Scale = "1.90",
		dialogType = 2,
		Background_Position = "313.56=694.00",
		playerName = "接头人",
		background = "98lajichang",
		playerId = "4999",
		id = "2309200426",
		playerPosType = 0,
		isStay = 0
	},
	["2309200427"] = {
		classId = 23092004,
		index = 27,
		Background_Scale = "1.90",
		playerLines = "也就是说，她们认为VLife作为独裁者，生态链最顶端的人，对于底层人民而言没有益处。",
		dialogType = 3,
		Background_Position = "313.56=694.00",
		background = "98lajichang",
		playerId = "4999",
		id = "2309200427",
		playerPosType = 0,
		isStay = 0
	},
	["2309200428"] = {
		classId = 23092004,
		index = 28,
		playerLines = "理解是能理解，但我不觉得仅凭这一点就能让她们心甘情愿赌上自己的一辈子。",
		Background_Scale = "1.90",
		dialogType = 3,
		Background_Position = "313.56=694.00",
		background = "98lajichang",
		playerId = "4999",
		id = "2309200428",
		playerPosType = 0,
		isStay = 0
	},
	["2309200429"] = {
		classId = 23092004,
		index = 29,
		Background_Scale = "1.90",
		playerLines = "我们立足于人民，为了人民而战，就算被认为是反派也无所谓。作为“班长”的你，应该也有过不得不扮黑脸的时候吧？",
		dialogType = 2,
		Background_Position = "313.56=694.00",
		playerName = "接头人",
		background = "98lajichang",
		playerId = "4999",
		id = "2309200429",
		playerPosType = 0,
		isStay = 0
	},
	["2309200430"] = {
		classId = 23092004,
		index = 30,
		playerLines = "所以你应该也清楚，无所谓别人是否理解我们，我们只为实现自己的目标而行动。",
		Background_Scale = "1.90",
		dialogType = 2,
		Background_Position = "313.56=694.00",
		playerName = "接头人",
		background = "98lajichang",
		playerId = "4999",
		id = "2309200430",
		playerPosType = 0,
		isStay = 0
	},
	["2309200431"] = {
		classId = 23092004,
		index = 31,
		Background_Scale = "1.90",
		playerLines = "我握住接头人伸过来的手，纤细却有力，仿佛诉说着她在推翻VLife的斗争中付出的一切。",
		dialogType = 3,
		Background_Position = "313.56=694.00",
		background = "98lajichang",
		playerId = "4999",
		id = "2309200431",
		playerPosType = 0,
		isStay = 0
	},
	["2309200432"] = {
