		playerId = "209620",
		id = "2309200607",
		playerExpression = "beixuan1",
		playerPosType = 2,
		isStay = 0
	},
	["2309200608"] = {
		classId = 23092006,
		index = 8,
		Player_Position = "0.00=-143.34",
		playerLines = "是啊，除去里德这种底层城市，像水都「诗蔻迪」和地月卫星城「萝塔」这种地方都得有公民证才能去。",
		dialogType = 2,
		Background_Scale = "0.45",
		playerName = "俱乐部常客",
		background = "98jiuba",
		playerId = "5019",
		id = "2309200608",
		playerPosType = 2,
		isStay = 0
	},
	["2309200609"] = {
