		index = 20,
		background = "fightbg4",
		id = "2404250820",
		dialogType = 2,
		playerLines = "或许是需要对上电波才能听到？",
		playerPosType = 0,
		isStay = 0
	},
	["2404250821"] = {
		classId = 24042508,
		index = 21,
		playerLines = "那是一个非常悲伤的声音...像是叹息、又像是求救...",
		dialogType = 2,
		playerName = "希丝奈",
		background = "fightbg4",
		playerId = "213320",
		id = "2404250821",
		playerPosType = 2,
		isStay = 0
	},
	["2404250822"] = {
		classId = 24042508,
		index = 22,
		playerLines = "不过可以确定的是，声音源自洞穴的深处。",
		dialogType = 2,
		playerName = "希丝奈",
		background = "fightbg4",
		playerId = "213320",
		id = "2404250822",
		playerPosType = 2,
		isStay = 0
	},
	["2404250823"] = {
		classId = 24042508,
		index = 23,
		playerLines = "既然如此，只要继续走下去，想必我们就能一步步接近声音的来源吧。",
