		playerName = "班长",
		background = "fightbg4",
		id = "2404250823",
		playerPosType = 0,
		isStay = 0
	},
	["2404250824"] = {
		classId = 24042508,
		index = 24,
		playerLines = "嗯，我相信会是这样。",
		dialogType = 2,
		playerName = "希丝奈",
		background = "fightbg4",
		playerId = "213320",
		id = "2404250824",
		playerPosType = 2,
		isStay = 0
	},
	["2404250825"] = {
		classId = 24042508,
		index = 25,
		playerLines = "哈哈，这下听懂了，总之就是要继续前进对吧。",
		dialogType = 2,
		playerName = "碧萝丝",
		background = "fightbg4",
		playerId = "203520",
		id = "2404250825",
		playerPosType = 2,
		isStay = 0
	},
	["2404250826"] = {
		classId = 24042508,
		index = 26,
		playerLines = "走吧，保持警惕，这里四处都可能会有埋伏。",
		dialogType = 2,
		playerName = "班长",
		background = "fightbg4",
		id = "2404250826",
		playerPosType = 0,
		isStay = 0
	},
	["2404250901"] = {
		classId = 24042509,
		index = 1,
		playerLines = "随着对洞穴的深入，我们终于见到了藏在这里的机器人，它们和刚刚在外面袭击我们的那只有着类似的外观，并且体内都搭载着一个玻璃罩子。",
		dialogType = 2,
		background = "fightbg4",
		playerId = "4999",
		id = "2404250901",
		playerPosType = 0,
		isStay = 0
	},
	["2404250902"] = {
		classId = 24042509,
		index = 2,
		playerLines = "碧萝丝本想与它们展开战斗，但奇怪的是，这些机器人似乎并没有攻击我们的意愿，只是呆呆地站在角落里一动不动。",
		dialogType = 2,
		background = "fightbg4",
		playerId = "4999",
		id = "2404250902",
		playerPosType = 0,
		isStay = 0
	},
	["2404250903"] = {
		classId = 24042509,
		index = 3,
		playerLines = "我们一度怀疑这些机器人已经报废，但考虑到它们身上的指示灯发着亮光，我们还是选择了绕路而行。",
		dialogType = 2,
		background = "fightbg4",
		playerId = "4999",
		id = "2404250903",
		playerPosType = 0,
		isStay = 0
	},
	["2404250904"] = {
		classId = 24042509,
		index = 4,
		playerLines = "感觉到现在为止一直在走迷宫呀......",
